import { Component } from 'react'
import { connect } from 'react-redux'
import { withRouter } from 'react-router'
import { Container } from '../../../../components'
import { CovidPolicyStyle } from './index.style'
import { SUN_LIFE_GOLD_CODE, COVID_PROTECTION } from '../../../../constants/pkgCode'
import { clearLocalStorage, setToLocalStorage } from '../../../../helpers/localstorage'
import { REDIRECT_URL } from '../../../../constants/cookies'
import { PAGE_CODE_CONFIG } from './config'
import ProductPkgCard from '../../../../components/ProductPkgCard'
import policyActions from '../../../../redux/policy/action'
import TermsAndConditionModal from './components/TermsAndConditionModal'

const { getPackages } = policyActions

export class CustomerPackages extends Component {
  constructor (props) {
    super(props)
    const { productCode } = props
    this.state = {
      showTermsModal: false,
      pageConfig: PAGE_CODE_CONFIG[productCode]
    }
    this.pkg = {}
  }

  componentDidMount () {
    if (this.props.productCode) {
      const { pageConfig } = this.state
      this.props.getPackages({
        code: this.props.productCode,
        package_type: pageConfig.packageType
      })
    }

    clearLocalStorage()
    setToLocalStorage(REDIRECT_URL, window.location.pathname)
  }

  handleBuyClick = (pkg) => {
    // handle buy click
    const { productCode } = this.props
    this.pkg = pkg
    if (productCode === COVID_PROTECTION) {
      this.handleCloseTerms()
    } else {
      this.handleBuyConfirm(this.pkg)
    }
  }

  handleUserConfirmed = () => {
    this.handleBuyConfirm(this.pkg)
    this.handleCloseTerms()
  }

  handleBuyConfirm = (pkg) => {
    const { pageConfig } = this.state
    const { leadTrackId } = this.props
    let path = `/${pageConfig.productType}/policy/holder/` // move the customer to policy holder details
    if (leadTrackId) {
      path = `${path}?tid=${leadTrackId}`
    }
    this.props.history.push({
      pathname: path,
      state: {
        covidPkg: pkg,
        agentRef: this.props.agentRef
      }
    })
  }

  handleCloseTerms = () => {
    this.setState(prevState => ({
      showTermsModal: !prevState.showTermsModal
    }))
  }

  render () {
    const { packageList = {}, pkgLoading, productCode } = this.props
    const { complete_match: completeMatch = [] } = packageList
    const { pageConfig, showTermsModal } = this.state
    return (
      <Container
        title='logo'
        loader={pkgLoading}
        showCustomerFaq={pageConfig.showFaq}
        showInnerHeader
        hideBottomTabs
      >
        <CovidPolicyStyle>
          {
            completeMatch.map(pkg => {
              return (
                <ProductPkgCard
                  productCode={productCode}
                  key={pkg.code}
                  pkg={pkg}
                  onBuyClick={this.handleBuyClick}
                  isRecommend={pkg.code === SUN_LIFE_GOLD_CODE}
                  showBuyBtn
                />
              )
            })
          }
        </CovidPolicyStyle>
        {
          showTermsModal && (
            <TermsAndConditionModal
              showTermsModal={showTermsModal}
              onClose={this.handleCloseTerms}
              onConfirmed={this.handleUserConfirmed}
            />
          )
        }
      </Container>
    )
  }
}

export default withRouter(
  connect(
    (state) => ({
      packageList: state.Policy.packages,
      pkgLoading: state.Loading.GET_PACKAGES
    }),
    {
      getPackages
    }
  )(CustomerPackages)
)
