import { Component } from 'react'
import PropTypes from 'prop-types'
import CovidPkgCard from './CovidPkgCard'
import { COVID_PROTECTION, JIWA_PROTECTION } from '../../constants/pkgCode'
import JiwaPkgCard from './JiwaPkgCard'

class ProductPkgCard extends Component {
  static propTypes = {
    productCode: PropTypes.string,
    pkg: PropTypes.object,
    index: PropTypes.number,
    showBuyBtn: PropTypes.bool,
    isRecommend: PropTypes.bool,
    showCommission: PropTypes.bool,
    onCardClick: PropTypes.func,
    onBuyClick: PropTypes.func
  }

  getProductPkgCard = () => {
    const { productCode } = this.props
    switch (productCode) {
      case COVID_PROTECTION:
        return <CovidPkgCard {...this.props} />
      case JIWA_PROTECTION:
        return <JiwaPkgCard {...this.props} />
      default:
        return null
    }
  }

  render () {
    return (
      <>
        {this.getProductPkgCard()}
      </>
    )
  }
}

export default ProductPkgCard
