import { Component } from 'react'
import PropTypes from 'prop-types'
import { TermsAndConditionStyle } from './index.style'
import Modal from '../../../../../../components/Modal'
import { LANG_STRINGS } from '../../../../../../lang'
import { COVID_CONFIRMATION_TERMS } from '../../../components/CovidTermsAndConditions/constants'
import { DisplayFlexRCC, Row, DisplayFlexCCC } from '../../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import CustomCheckbox from '../../../../../../components/CustomCheckbox'

class TermsAndConditionModal extends Component {
  static propTypes = {
    showTermsModal: PropTypes.bool,
    onClose: PropTypes.func,
    onConfirmed: PropTypes.func
  }

  state = {
    isConfirmed: false
  }

  handleCheckbox = () => {
    this.setState((prevState) => ({
      isConfirmed: !prevState.isConfirmed
    }))
  }

  renderTermsSection = (term, index) => {
    const { listClass, terms = [], customerService = [], type } = term
    return (
      <>
        <div className='terms-title'>{index ? `${index}. ` : ''}{term.title}</div>
        {term.subTitle2 && <div className='terms-subtitle-2'>{term.subTitle2}</div>}
        {
          !!terms.length && (
            <ol className={listClass} type={type || '1'}>
              {
                terms.map(item => (
                  typeof item === 'object' ? (
                    <li>
                      <div className={item.className}>{item.title}</div>
                      {this.renderTerms(item)}
                    </li>
                  )
                    : (<li dangerouslySetInnerHTML={{ __html: item }} />)
                ))
              }
            </ol>
          )
        }
        {
          !!customerService.length && (
            customerService.map(service => (
              this.renderCards(service)
            ))
          )
        }
      </>
    )
  }

  renderSubTerms = (item = {}) => {
    const { title } = item
    return (
      <>
        <CustomText color={AgentColorPallette.black} size='14px' weight={700}>
          {title}
        </CustomText>
        {
          this.renderTerms(item)
        }
      </>
    )
  }

  renderTerms = (data) => {
    const { listClass, type, terms } = data
    if (Array.isArray(data)) return
    return (
      <>
        <ol className={`${listClass} marginOL`} type={type || '1'}>
          {
            terms.map((item, index) => (
              typeof item === 'object' ? this.renderSubTerms(item) : <li key={`co-terms${index}`}>{item}</li>
            ))
          }
        </ol>
        {
          !!data.bottom && (
            <CustomText
              size='11px'
              weight={700}
              top='2px'
              color={AgentColorPallette.black}
            >
              {data.bottom}
            </CustomText>
          )
        }
      </>
    )
  }

  renderCards = (card) => {
    return (
      <Row className='customer-card'>
        <DisplayFlexRCC className='card-icon'>
          <img src={card.icon} alt='' />
        </DisplayFlexRCC>
        <div className='casd-right-section'>
          <CustomText
            size='12px'
            color={AgentColorPallette.black}
            weight='700'
          >
            {card.title}
          </CustomText>
          <CustomText
            size='12px'
            top='2px'
            weight='700'
            color={AgentColorPallette.fontDarkerGrey}
            dangerouslySetInnerHTML={{ __html: card.subtitle }}
          />
        </div>
      </Row>
    )
  }

  render () {
    const { showTermsModal, onClose, onConfirmed } = this.props
    return (
      <Modal
        heading={LANG_STRINGS.termsConditions}
        isOpen={showTermsModal}
        onClose={onClose}
        className='covid-terms-modal'
      >
        <TermsAndConditionStyle>
          <div className='terms-container'>
            {
              COVID_CONFIRMATION_TERMS.map(terms => this.renderTermsSection(terms))
            }
          </div>
          <div className='btm-container'>
            <DisplayFlexRCC>
              <a href='/pis-proteksi-plus.pdf' className='btn-anchor' download>
                {LANG_STRINGS.productInformationSummary}
              </a>
            </DisplayFlexRCC>
            <DisplayFlexCCC className='confitmation-container'>
              <Row justify='space-between' align='center' className='checkbox-confirm'>
                <CustomCheckbox
                  isChecked={this.state.isConfirmed}
                  onChange={this.handleCheckbox}
                  name='userConfirmation'
                  id='userConfirmation'
                  bgColor={AgentColorPallette.primary}
                  color={AgentColorPallette.black}
                />
                <CustomText color={AgentColorPallette.black}>
                  {LANG_STRINGS.userConfirmationStatement}
                </CustomText>
              </Row>
              <Button onClick={onConfirmed} disabled={!this.state.isConfirmed}>
                {LANG_STRINGS.next}
              </Button>
            </DisplayFlexCCC>
          </div>
        </TermsAndConditionStyle>
      </Modal>
    )
  }
}

export default TermsAndConditionModal
