import { Component } from 'react'
import PropTypes from 'prop-types'
import { get as lodashGet } from 'lodash'
import { CovidPkgCardStyle, CovidCardHeader, CovidCardBody } from '../index.style'
import { Row, DisplayFlexRCSB, DisplayFlexRCC } from '../../../commonStyle/index.style'
import { RECOMMENDED, ALLIANZ } from '../../../images'
import CustomText from '../../CustomText'
import { LANG_STRINGS } from '../../../lang'
import { formatMoney } from '../../../helpers/utility'
import { AgentColorPallette } from '../../../configs/colorPallete'
import Button from '../../Button'
import { JIWA_POLICY_CONFIG } from '../../../constants/pkgCode'

class JiwaPkgCard extends Component {
  static propTypes = {
    pkg: PropTypes.object,
    index: PropTypes.number,
    showBuyBtn: PropTypes.bool,
    isRecommend: PropTypes.bool,
    showCommission: PropTypes.bool,
    onCardClick: PropTypes.func,
    onBuyClick: PropTypes.func
  }

  handleBuyPkg = (pkgConfig) => {
    // this is handle buy package
    this.props.onBuyClick({
      ...this.props.pkg,
      ...pkgConfig
    })
  }

  getBodyContent = (title, subTitle, index) => {
    return (
      <div key={`pkgCard_${index}`} className='card-body-content' id={`covidPkgDeathBenefit${index}`}>
        <CustomText
          color={AgentColorPallette.black}
          bottom='4px'
          weight={800}
        >
          {title}
        </CustomText>
        <CustomText color={AgentColorPallette.fontSemiGrey} size='13px'>
          {LANG_STRINGS.sumAssuredOf}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          size='13px'
          weight={800}
        >
          {subTitle}
        </CustomText>
      </div>
    )
  }

  render () {
    const { showBuyBtn, isRecommend, onCardClick = () => {}, pkg = {}, index, showCommission } = this.props
    const pkgConfig = lodashGet(JIWA_POLICY_CONFIG, `${pkg.code}`, {}) || {}
    return (
      <CovidPkgCardStyle onClick={onCardClick} id={`covidPkgCard${index}`}>
        <CovidCardHeader bgColor={pkgConfig.backgroundColor} id={`covidPkgName${index}`}>
          <Row>
            <img className='pkg-logo' src={ALLIANZ} alt='' />
          </Row>
          <Row align='center'>
            <CustomText size='13px'>
              {pkg.name}
            </CustomText>
          </Row>
        </CovidCardHeader>
        <CovidCardBody>
          {
            isRecommend && (
              <div className='recommended-img'>
                <img src={RECOMMENDED} alt='' />
              </div>
            )
          }
          {
            pkg.benefit.data.length && pkg.benefit.data.map((benefit, index) => {
              return (
                this.getBodyContent(
                  benefit.description,
                  benefit.sum_insured,
                  (index + 1)
                )
              )
            })
          }
          <hr className='card-hr' />
        </CovidCardBody>
        <div className='card-bottom-section'>
          <DisplayFlexRCSB id={`covidPkgCardPremium${index}`}>
            <div>
              <CustomText color={AgentColorPallette.black} weight={800}>
                {LANG_STRINGS.premium}
              </CustomText>
              <CustomText color={AgentColorPallette.black}>
                / {LANG_STRINGS.person} / 12 {LANG_STRINGS.months}
              </CustomText>
            </div>
            <CustomText
              color={AgentColorPallette.black}
              size='20px'
              weight={800}
            >
              {formatMoney(pkg.premium.amount, 0)}
            </CustomText>
          </DisplayFlexRCSB>
          {
            showCommission && (
              <>
                <hr className='agent-hr' />
                <DisplayFlexRCSB>
                  <CustomText
                    color={AgentColorPallette.darkerGold}
                    size='16px'
                    weight={700}
                  >
                    {LANG_STRINGS.commissionForPartner}
                  </CustomText>
                  <CustomText
                    color={AgentColorPallette.darkerGold}
                    size='16px'
                    weight={800}
                  >
                    {formatMoney(pkg.commission, 0)}
                  </CustomText>
                </DisplayFlexRCSB>
              </>
            )
          }
        </div>
        {
          showBuyBtn && (
            <DisplayFlexRCC className='card-action'>
              <Button onClick={() => this.handleBuyPkg(pkgConfig)}>
                {LANG_STRINGS.buyPackage}
              </Button>
            </DisplayFlexRCC>
          )
        }
      </CovidPkgCardStyle>
    )
  }
}

export default JiwaPkgCard
