import { Component } from 'react'
import PropTypes from 'prop-types'
import { Container } from '../../../../components'
import AdiraPackageDetails from '../../../CommonContainer/AdiraPackageDetails'
import { LANG_STRINGS } from '../../../../lang'
import StepsHeader from '../../../../components/StepsHeader'
import { CustomerMotorStyle } from './index.style'
import { withRouter } from 'react-router'
import { POLICY_DATA_KEY } from '../../../../constants/cookies'
import { removeFromLocalStorageData } from '../../../../helpers/localstorage'

class MotorPkgDetails extends Component {
  static propTypes = {
    productCode: PropTypes.string
  }

  handleBuyNow = () => {
    // go to buy now section
    removeFromLocalStorageData(POLICY_DATA_KEY)
    let pathname = `/motor/form/${this.props.productCode}/${this.props.agentRef}`
    if (this.props.leadTrackId) {
      // if lead track id exist then add as query param to update the lead status
      pathname = `${pathname}/?tid=${this.props.leadTrackId}`
    }
    this.props.history.push({
      pathname
    })
  }

  render () {
    return (
      <Container
        title={LANG_STRINGS.motorCycleInsurance}
        hideBottomTabs
        mitraHeader
      >
        <CustomerMotorStyle>
          <StepsHeader
            className='steps-header-custom'
            leftText={LANG_STRINGS.selectPkg}
            current='1'
            totalSteps='4'
          />
          <AdiraPackageDetails
            btnText={LANG_STRINGS.buyNow}
            onInsuranceBtnClick={this.handleBuyNow}
          />
        </CustomerMotorStyle>
      </Container>
    )
  }
}

export default withRouter(MotorPkgDetails)
