import { Component } from 'react'
import { connect } from 'react-redux'
import { getParamsFromUri } from '../../../../helpers/utility'
import { JIWA_PROTECTION, COVID_PROTECTION, BIKE_PROTECTION_LITE, HEALTH_PROTECTION } from '../../../../constants/pkgCode'
import NotFoundPage from '../../NotFoundPage'
import CustomerPackages from '../CustomerPackages'
import MotorPkgDetail from '../MotorPkgDetails'
import leadActions from '../../../../redux/lead/actions'
import LippoHCPPkgs from '../LippoHCP/LippoHCPPkgs'

const { openLeadRequest } = leadActions

class ReferPages extends Component {
  componentDidMount () {
    const leadTrackId = getParamsFromUri.call(this, 'leadTrackId')
    if (leadTrackId) {
      this.props.openLeadRequest({
        leadId: leadTrackId
      })
    }
  }

  renderReferPages = () => {
    const productCode = getParamsFromUri.call(this, 'productCode')
    const agentRef = getParamsFromUri.call(this, 'agentRef')
    const leadTrackId = getParamsFromUri.call(this, 'leadTrackId')
    const containerProp = {
      productCode,
      agentRef,
      leadTrackId
    }

    switch (productCode) {
      case JIWA_PROTECTION:
      case COVID_PROTECTION:
        return <CustomerPackages {...containerProp} />
      case BIKE_PROTECTION_LITE:
        return <MotorPkgDetail {...containerProp} />
      case HEALTH_PROTECTION:
        return <LippoHCPPkgs {...containerProp} />
      default:
        return <NotFoundPage hideBottomTabs />
    }
  }

  render () {
    return (
      <>
        {
          this.renderReferPages()
        }
      </>
    )
  }
}

export default connect(
  state => ({

  }),
  {
    openLeadRequest
  }
)(ReferPages)
